41	   * Player/Annotate's existing "who's selected" box-only treatment is
42	   * unchanged.
43	   */
44	  dimUnhighlighted?: boolean;
45	  /**
46	   * Hand-labelled stretches where the tracker's red/blue assignment is known
47	   * to be flipped (`fighter_frames.corner` is deliberately left uncorrected —
48	   * see label-events-corner-is-box-not-person). When the current frame falls
49	   * inside one of these, box/skeleton colour is flipped for **display only**;
50	   * nothing about the underlying data changes.
51	   */
52	  cornerSwapSpans?: CornerSwapSpan[];
53	}
54	
55	export interface FighterOverlayHandle {
56	  draw: (frame: number) => void;
57	}
58	
59	const FighterOverlay = forwardRef<FighterOverlayHandle, FighterOverlayProps>(
60	  ({ frameMap, fightWidth, fightHeight, showBoxes, showSkeletons, highlightCorner = null, dimUnhighlighted = false, cornerSwapSpans = [] }, ref) => {
61	    const canvasRef = useRef<HTMLCanvasElement>(null);
62	    const frameMapRef = useRef(frameMap);
63	    const fightWidthRef = useRef(fightWidth);
64	    const fightHeightRef = useRef(fightHeight);
65	    const showBoxesRef = useRef(showBoxes);
66	    const showSkeletonsRef = useRef(showSkeletons);
67	    const highlightCornerRef = useRef(highlightCorner);
68	    const dimUnhighlightedRef = useRef(dimUnhighlighted);
69	    const cornerSwapSpansRef = useRef(cornerSwapSpans);
70	    const lastFrameRef = useRef(1);
71	
72	    useEffect(() => { frameMapRef.current = frameMap; }, [frameMap]);
73	    useEffect(() => { fightWidthRef.current = fightWidth; }, [fightWidth]);
74	    useEffect(() => { fightHeightRef.current = fightHeight; }, [fightHeight]);
75	    useEffect(() => { showBoxesRef.current = showBoxes; }, [showBoxes]);
76	    useEffect(() => { showSkeletonsRef.current = showSkeletons; }, [showSkeletons]);
77	    useEffect(() => { dimUnhighlightedRef.current = dimUnhighlighted; }, [dimUnhighlighted]);
78	    useEffect(() => { cornerSwapSpansRef.current = cornerSwapSpans; }, [cornerSwapSpans]);
79	
80	    const render = () => {
81	      const canvas = canvasRef.current;
82	      if (!canvas) return;
83	      const ctx = canvas.getContext('2d');
84	      if (!ctx) return;
85	
86	      if (canvas.width !== canvas.clientWidth || canvas.height !== canvas.clientHeight) {
87	        canvas.width = canvas.clientWidth;
88	        canvas.height = canvas.clientHeight;
89	      }
90	      ctx.clearRect(0, 0, canvas.width, canvas.height);
91	
92	      const drawSkeletons = showSkeletonsRef.current;
93	      const drawBoxes = showBoxesRef.current;
94	      if (!drawBoxes && !drawSkeletons) return;
95	
96	      const frame = lastFrameRef.current;
97	      const detections = frameMapRef.current.get(frame);
98	      if (!detections) return;
99	
100	      const scaleX = canvas.width / fightWidthRef.current;
101	      const scaleY = canvas.height / fightHeightRef.current;
102	      const highlight = highlightCornerRef.current;
103	      // Display-only correction: a confirmed corner_swap span means the
104	      // tracker's red/blue assignment is known-flipped here. fighter_frames.corner
105	      // itself is never touched (see the prop docs above) — only which
106	      // colour we draw it as.
107	      const swapped = isFrameSwapped(frame, cornerSwapSpansRef.current);
108	
109	      for (const d of detections) {
110	        const displayCorner = swapped ? 1 - d.corner : d.corner;
111	        const color = displayCorner === 0 ? COLOR_RED : COLOR_BLUE;
112	        const isSelected = highlight !== null && highlight === d.corner;
113	
114	        // The box stays hidden until this fighter's corner is selected. Static styling
115	        // mirrors the selected fighter-corner-btn (tinted fill + glow, no motion).
116	        if (drawBoxes && isSelected) {
117	          const x = d.x1 * scaleX;
118	          const y = d.y1 * scaleY;
119	          const w = (d.x2 - d.x1) * scaleX;
120	          const h = (d.y2 - d.y1) * scaleY;
121	
122	          const radius = Math.min(12, w / 2, h / 2);
123	
124	          ctx.save();
125	          ctx.beginPath();
126	          ctx.roundRect(x, y, w, h, radius);
127	          ctx.fillStyle = withAlpha(color, 0.12);
128	          ctx.fill();
129	
130	          ctx.shadowColor = color;
131	          ctx.shadowBlur = 14;
132	          ctx.strokeStyle = color;
133	          ctx.lineWidth = 2;
134	          ctx.stroke();
135	          ctx.restore();
136	        }
137	
138	        if (drawSkeletons && d.keypoints && d.keypoints.length === 17) {
139	          const dim = dimUnhighlightedRef.current && highlight !== null && !isSelected;
140	
141	          ctx.save();
142	          if (dim) ctx.globalAlpha = 0.3;
143	          ctx.strokeStyle = color;
144	          ctx.fillStyle = color;
145	          ctx.lineWidth = 1.5;
146	
147	          // Draw skeleton edges
148	          for (const [a, b] of SKELETON_EDGES) {
149	            const pa = d.keypoints[a];
150	            const pb = d.keypoints[b];
151	            if (!pa || !pb) continue;
152	            const ax = pa[0] * scaleX;
153	            const ay = pa[1] * scaleY;
154	            const bx = pb[0] * scaleX;
155	            const by = pb[1] * scaleY;
156	            ctx.beginPath();
157	            ctx.moveTo(ax, ay);
158	            ctx.lineTo(bx, by);
159	            ctx.stroke();
160	          }
161	
162	          // Draw joint dots
163	          for (const kp of d.keypoints) {
164	            if (!kp) continue;
165	            ctx.beginPath();
166	            ctx.arc(kp[0] * scaleX, kp[1] * scaleY, 3, 0, Math.PI * 2);
167	            ctx.fill();
168	          }
169	          ctx.restore();
170	        }
171	      }
172	    };
173	
174	    useImperativeHandle(ref, () => ({
175	      draw(frame: number) {
176	        lastFrameRef.current = frame;
177	        render();
178	      },
179	    }));
180	
181	    useEffect(() => {
182	      highlightCornerRef.current = highlightCorner;
183	      render();
184	      // eslint-disable-next-line react-hooks/exhaustive-deps
185	    }, [highlightCorner]);
186	
187	    return (
188	      <canvas
189	        ref={canvasRef}
190	        style={{
191	          position: 'absolute',
192	          top: 0,
193	          left: 0,
194	          width: '100%',
195	          height: '100%',
196	          pointerEvents: 'none',
197	        }}
198	      />
199	    );
200	  },
201	);
202	
203	FighterOverlay.displayName = 'FighterOverlay';
204	export default FighterOverlay;
